const groupLogsByType = (
  rawBuildLogs: BuildLog[],
  filterType: 'all' | 'errors' | 'warnings',
): BuildLogGroup[] => {
  if (filterType === 'all') {
    return [{ hidden: false, logs: rawBuildLogs }];
  }

  const logs = rawBuildLogs.map((log, index) => ({ ...log, index }));
  const groupedLogs: BuildLogGroup[] = [];

  let currentGroup: BuildLog[] = [];
  let currentGroupType: 'all' | 'errors' | 'warnings';

